def attr(field, value, raw=None, unit=None, attribution=None):
    return dict(field=field, value=value, unit=unit, raw=raw or str(value), attribution=attribution)

def entity(label, types, count=None, attributes=(), craft="not_established", scope="group", flags=()):
    return dict(label=label, reportedTypes=types, count=count, attributes=list(attributes), craftAssociation=craft, scope=scope, reviewFlags=list(flags))

